function hasValues(a){return a.some(function(p){return p.value!==undefined})}

/* Why there is no chart, said plainly: no usable file; no candles on file for the stock (never fetched); or too few VALID candles (the count is the cleaned one,
   so invalid rows never count). The same wording is used by the Technical Snapshot. Nothing is filled in. */
var NOT_FETCHED="No price history has been fetched for this stock yet.";
function historyError(doc,sym,valid){
  if(!doc||typeof doc!=="object"||!doc.stocks||typeof doc.stocks!=="object"||Array.isArray(doc.stocks))return"Historical data unavailable.";
  var st=Object.prototype.hasOwnProperty.call(doc.stocks,sym)?doc.stocks[sym]:null;
  if(!st||typeof st!=="object"||!Array.isArray(st.candles)||!st.candles.length)return NOT_FETCHED;
  return"Not enough historical data: "+valid+" valid daily candle"+(valid===1?"":"s")+" on file; at least "+MIN_CANDLES+" are needed."}

function unavailable(text){return '<h3 style="margin:1.4em 0 .4em">Technical Snapshot</h3><p class="note" style="padding-left:0">'+esc(text||"Historical data unavailable.")+'</p>'}
/* Same wording as the price chart (SLChart.historyError): no usable file; no candles on file for the stock; or fewer VALID candles than the chart needs.
   With a few valid candles the snapshot still shows what they support (the rest stays "-") and says how many there are. Nothing is filled in. */
var MIN_CHART=30;
function status(doc,sym){
  if(!doc||typeof doc!=="object"||!doc.stocks||typeof doc.stocks!=="object"||Array.isArray(doc.stocks))return{text:"Historical data unavailable.",valid:0};
  var st=Object.prototype.hasOwnProperty.call(doc.stocks,sym)?doc.stocks[sym]:null;
  if(!st||typeof st!=="object"||!Array.isArray(st.candles)||!st.candles.length)return{text:"No price history has been fetched for this stock yet.",valid:0};
  var n=cleanCandles(st.candles).length;
  return{text:n<MIN_CHART?"Not enough historical data: "+n+" valid daily candle"+(n===1?"":"s")+" on file; at least "+MIN_CHART+" are needed.":null,valid:n}}
